function validate(input) {
  const lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (input.length !== 4) return 'Give four dates.';
  for (const date of input) {
    if (typeof date !== 'string' || !/^\d\d-\d\d$/.test(date)) return 'Each date must look like "MM-DD".';
    const month = Number(date.slice(0, 2));
    const day = Number(date.slice(3, 5));
    if (month < 1 || month > 12 || day < 1 || day > lengths[month - 1]) return `${date} is not a day of a non-leap year.`;
  }
  const [arriveAlice, leaveAlice, arriveBob, leaveBob] = input;
  if (arriveAlice > leaveAlice) return 'Alice must arrive on or before the day she leaves.';
  if (arriveBob > leaveBob) return 'Bob must arrive on or before the day he leaves.';
  return null;
}

