function countDaysTogether(arriveAlice, leaveAlice, arriveBob, leaveBob) {
  const monthDays = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const daysBefore = [0];
  for (const days of monthDays) {
    daysBefore.push(daysBefore[daysBefore.length - 1] + days);
  }
  const toDay = (date) => daysBefore[Number(date.slice(0, 2)) - 1] + Number(date.slice(3, 5));
  const start = Math.max(toDay(arriveAlice), toDay(arriveBob));
  const end = Math.min(toDay(leaveAlice), toDay(leaveBob));
  return Math.max(0, end - start + 1);
}

