function countDaysTogether(arriveAlice, leaveAlice, arriveBob, leaveBob) {
  const lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const pad = (x) => String(x).padStart(2, '0');
  let together = 0;
  // "MM-DD" strings sort in calendar order, so plain string comparison works.
  for (let month = 1; month <= 12; month++) {
    for (let day = 1; day <= lengths[month - 1]; day++) {
      const date = pad(month) + '-' + pad(day);
      const alice = arriveAlice <= date && date <= leaveAlice;
      const bob = arriveBob <= date && date <= leaveBob;
      if (alice && bob) together++;
    }
  }
  return together;
}

