function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const pad = (x) => String(x).padStart(2, '0');
  const toDate = (n) => {
    let month = 0;
    while (n > lengths[month]) { n -= lengths[month]; month++; }
    return pad(month + 1) + '-' + pad(n);
  };
  // Short stays near each other make touching and nearly touching stays common.
  const stay = (center) => {
    const reach = size === 'small' ? int(0, 40) : int(0, 200);
    const a = Math.min(365, Math.max(1, center + int(-reach, reach)));
    const b = Math.min(365, Math.max(1, a + int(0, reach)));
    return [toDate(a), toDate(b)];
  };
  const center = int(1, 365);
  const [arriveAlice, leaveAlice] = rand() < 0.2 ? stay(int(1, 365)) : stay(center);
  const [arriveBob, leaveBob] = stay(center);
  return [arriveAlice, leaveAlice, arriveBob, leaveBob];
}
